  4	public final class BubbleSort {
  5	    @FunctionalInterface
  6	    private interface BubblePassRunner {
  7	        boolean run(int unsortedEnd);
  8	    }
  9	
 10	    @FunctionalInterface
 11	    private interface IndexPairComparator {
 12	        boolean shouldSwap(int leftIndex, int rightIndex);
 13	    }
 14	
 15	    @FunctionalInterface
 16	    private interface IndexPairSwapper {
 17	        void swap(int leftIndex, int rightIndex);
 18	    }
 19	
 20	    private BubbleSort() {
 21	    }
 22	
 23	    public static void sort(int[] array) {
 24	        if (array == null || array.length < 2) {
 25	            return;
 26	        }
 27	
 28	        runBubbleSort(
 29	            array.length,
 30	            unsortedEnd -> bubbleLargestValueToEnd(
 31	                unsortedEnd,
 32	                (leftIndex, rightIndex) -> array[leftIndex] > array[rightIndex],
